\subsection{Definitions and mathematical statement}
\paragraph{Shared notation.}$\mathbb N$, $\mathbb Z$, $\mathbb Q$, $\mathbb R$, and $\mathbb C$ denote the natural numbers, integers, rationals, reals, and complex numbers, respectively. All additional parameters and hypotheses are specified in the question.


\paragraph{Statement recorded in the supplied source.}
Does every finite set of $m$-dimensional vectors of Euclidean norm at most $1$, whose vector sum has norm at most $1$, admit a permutation whose every prefix sum has norm at most $\sqrt{2.7m}$ and whose block sums are uniformly bounded by an absolute constant?
\par\smallskip\textit{Formulation references:} \href{https://huggingface.co/datasets/ulamai/UnsolvedMath}{[S1]}, \href{https://doi.org/10.4171/owr/2004/28}{[S2]}.

\subsection{Short English statement}
Does every finite set of $m$-dimensional vectors of Euclidean norm at most $1$, whose vector sum has norm at most $1$, admit a permutation whose every prefix sum has norm at most $\sqrt{2.7m}$ and whose block sums are uniformly bounded by an absolute constant?

\subsection{Sources}
\begin{itemize}
\item[S1] ULAM.AI and the UnsolvedMath Contributors, UnsolvedMath: A Curated Collection of Open Mathematics Problems, record 30000055 (OWR-730-001). Catalogue attribution under CC BY 4.0.
\url{https://huggingface.co/datasets/ulamai/UnsolvedMath}.
\item[S2] Original problem formulation and mathematical context.
\url{https://doi.org/10.4171/owr/2004/28}.
\end{itemize}
\label{end:30000055}

